\set ON_ERROR_STOP on
begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',label;end if;end$$;
create function pg_temp.reject(q text,code text) returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=code then return;end if;raise;end;raise exception 'FAIL accepted %',q;end$$;
create function pg_temp.session_hash(n integer default 1) returns text language sql volatile as $$select encode(sha256(convert_to('detailing-request-fixture:'||txid_current()::text||':'||pg_backend_pid()::text||':'||n::text,'UTF8')),'hex')$$;
create function pg_temp.fixture_id(n integer) returns uuid language sql stable as $$select md5('detailing-reservation-fixture:'||txid_current()::text||':'||pg_backend_pid()::text||':'||n::text)::uuid$$;
insert into auth.users(id,email) values(pg_temp.fixture_id(1),'detail-request-sql-owner@example.test');
select public.create_staging_business(pg_temp.fixture_id(1),pg_temp.fixture_id(2),'Detailing requests','detail-request-sql','UTC','USD','AUTO_DETAILING','detail-request-business-sql-001');
select public.create_auto_detailing_offer(pg_temp.fixture_id(1),pg_temp.fixture_id(2),pg_temp.fixture_id(4),'{"name":"Detail menu","description":"","currency":"USD","durationMinutes":60,"packages":[{"id":"basic","label":"Basic","amount":15000}],"vehicles":[{"id":"suv","label":"SUV","multiplierBp":12500}],"addons":[{"id":"pet-hair","name":"Pet hair","amount":3000}],"locations":[{"id":"mobile","label":"Mobile","amount":2000}],"idempotencyKey":"detail-request-offer-sql-001"}');
select public.create_auto_detailing_offer_scheduling(pg_temp.fixture_id(1),pg_temp.fixture_id(2),pg_temp.fixture_id(4),'UTC','[{"weekday":1,"startMinute":540,"endMinute":1020,"capacity":1}]',0,30,30,'detail-request-schedule-sql-001');
select public.save_detailing_draft(pg_temp.fixture_id(1),pg_temp.fixture_id(2),pg_temp.fixture_id(3),pg_temp.fixture_id(4),0,'Detail requests','#4f46e5','stacked');
select public.publish_detailing_draft(pg_temp.fixture_id(1),pg_temp.fixture_id(2),pg_temp.fixture_id(3),1,pg_temp.fixture_id(5),pg_temp.fixture_id(6),'["https://checkout.example.test"]');
select public.issue_detailing_flow_session(pg_temp.fixture_id(6),pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]');
create function pg_temp.choice() returns jsonb language sql as $$select '{"packageId":"basic","vehicleId":"suv","addonIds":["pet-hair"],"locationId":"mobile"}'::jsonb$$;
create function pg_temp.customer() returns jsonb language sql as $$select '{"name":"SQL fictional","email":"detail-request-fictional@example.test"}'::jsonb$$;
create function pg_temp.start_at() returns timestamptz language sql as $$select date_trunc('day',now())+interval '1 day 9 hours'$$;
create function pg_temp.model() returns jsonb language sql security definer set search_path=pg_catalog as $$select lumin.detailing_request_model(service_snapshot,pg_temp.choice(),pg_temp.customer(),pg_temp.start_at()) from public.bound_flow_versions where tenant_id=pg_temp.fixture_id(2) and flow_id=pg_temp.fixture_id(3) and version_id=pg_temp.fixture_id(5)$$;
create function pg_temp.request(k text default 'detail-request-operation-sql-001',c jsonb default pg_temp.choice(),price jsonb default pg_temp.model()->'pricing') returns jsonb language sql as $$select public.submit_detailing_reservation(pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]',k,c,pg_temp.customer(),pg_temp.start_at(),price)$$;
select pg_temp.assert((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.detailing_request_receipts'::regclass),'private forced RLS');
select pg_temp.assert(not has_table_privilege('service_role','public.detailing_request_receipts','SELECT') and not has_table_privilege('service_role','public.detailing_request_receipts','INSERT') and not has_table_privilege('authenticated','public.detailing_request_receipts','SELECT'),'no direct private grants');
select pg_temp.assert((select bool_and(prosecdef and proconfig=array['search_path=pg_catalog']) from pg_proc where oid in('lumin.detailing_request_model(jsonb,jsonb,jsonb,timestamptz)'::regprocedure,'public.detailing_reservation_context(text,text,jsonb)'::regprocedure,'public.detailing_reservation_target(text,text,jsonb)'::regprocedure,'public.submit_detailing_reservation(text,text,jsonb,text,jsonb,jsonb,timestamptz,jsonb)'::regprocedure)),'fixed definer authority');
select pg_temp.assert(not has_function_privilege('service_role','lumin.detailing_request_model(jsonb,jsonb,jsonb,timestamptz)','EXECUTE') and has_function_privilege('service_role','public.submit_detailing_reservation(text,text,jsonb,text,jsonb,jsonb,timestamptz,jsonb)','EXECUTE'),'only fixed public server RPC grants');
set local role anon;select pg_temp.reject($q$select pg_temp.request()$q$,'42501');select pg_temp.reject($q$select * from public.detailing_request_receipts$q$,'42501');reset role;
set local role authenticated;select pg_temp.reject($q$select pg_temp.request()$q$,'42501');select pg_temp.reject($q$insert into public.detailing_request_receipts values(null,null,null,'{}','{}')$q$,'42501');reset role;
set local role service_role;
select pg_temp.reject($q$select public.detailing_reservation_context(pg_temp.session_hash(),'https://foreign.example.test','["https://checkout.example.test"]')$q$,'42501');
select pg_temp.reject($q$select public.detailing_reservation_target(pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]')$q$,'P0002');
select pg_temp.reject($q$select pg_temp.request(c=>pg_temp.choice()||'{"price":1}')$q$,'22023');select pg_temp.reject($q$select pg_temp.request(c=>pg_temp.choice()||'{"addonIds":["foreign"]}')$q$,'22023');select pg_temp.reject($q$select pg_temp.request(c=>pg_temp.choice()||'{"addonIds":["pet-hair","pet-hair"]}')$q$,'22023');select pg_temp.reject($q$select pg_temp.request(price=>jsonb_set(pg_temp.model()->'pricing','{total,amount}','1'))$q$,'22023');
reset role;
-- A private provenance failure leaves no customer, booking, outbox or request orphan.
create function pg_temp.fail_request() returns trigger language plpgsql as $$begin if new.tenant_id=pg_temp.fixture_id(2) then raise exception 'FIXTURE_FAILURE';end if;return new;end$$;
create trigger fixture_detailing_request_failure before insert on public.detailing_request_receipts for each row execute function pg_temp.fail_request();select pg_temp.reject($q$select pg_temp.request()$q$,'P0001');drop trigger fixture_detailing_request_failure on public.detailing_request_receipts;
select pg_temp.assert((select count(*)=0 from public.bookings where tenant_id=pg_temp.fixture_id(2)) and(select count(*)=0 from public.customers where tenant_id=pg_temp.fixture_id(2)) and(select count(*)=0 from public.flow_requests where tenant_id=pg_temp.fixture_id(2)) and(select count(*)=0 from public.durable_outbox where tenant_id=pg_temp.fixture_id(2)),'atomic no orphan');
set local role service_role;
select pg_temp.assert(pg_temp.request()#>>'{receipt,pricing,total,amount}'='25000','unchanged package/addon/location vehicle model');select pg_temp.assert(pg_temp.request()->>'replayed'='true','exact replay');
select pg_temp.reject($q$select pg_temp.request(k=>'detail-request-different-key-sql-001')$q$,'40001');
select pg_temp.assert(public.detailing_reservation_target(pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]')#>>'{receipt,state}'='draft','persisted exact target');
select pg_temp.reject($q$select public.customer_flow_hold_target(pg_temp.session_hash(),'https://checkout.example.test')$q$,'0A000');select pg_temp.reject($q$select public.customer_flow_payment_target(pg_temp.session_hash(),'https://checkout.example.test')$q$,'0A000');reset role;
select pg_temp.assert((select count(*)=1 from public.bookings where tenant_id=pg_temp.fixture_id(2)) and(select count(*)=1 from public.flow_requests where tenant_id=pg_temp.fixture_id(2)) and(select count(*)=1 from public.detailing_request_receipts where tenant_id=pg_temp.fixture_id(2)),'one canonical request');
select pg_temp.reject($q$delete from public.detailing_request_receipts where tenant_id=pg_temp.fixture_id(2)$q$,'55000');
update public.bookings set pricing='{}' where tenant_id=pg_temp.fixture_id(2);select pg_temp.reject($q$select public.detailing_reservation_target(pg_temp.session_hash(),'https://checkout.example.test','["https://checkout.example.test"]')$q$,'40001');update public.bookings set pricing=pg_temp.model()->'pricing' where tenant_id=pg_temp.fixture_id(2);
update public.availability_rules set capacity=2 where tenant_id=pg_temp.fixture_id(2);select pg_temp.reject($q$select pg_temp.request()$q$,'40001');update public.availability_rules set capacity=1 where tenant_id=pg_temp.fixture_id(2);
update public.tenant_members set role='BUSINESS_STAFF' where tenant_id=pg_temp.fixture_id(2);select pg_temp.reject($q$select pg_temp.request()$q$,'42501');update public.tenant_members set role='BUSINESS_OWNER' where tenant_id=pg_temp.fixture_id(2);
update public.flow_sessions set expires_at=clock_timestamp()-interval '1 second' where tenant_id=pg_temp.fixture_id(2);select pg_temp.reject($q$select pg_temp.request()$q$,'42501');
select pg_temp.assert((select count(*)=0 from public.payments where tenant_id=pg_temp.fixture_id(2)) and(select count(*)=0 from public.capacity_holds where tenant_id=pg_temp.fixture_id(2)),'no payment/confirmation/hold writer in request RPC');
rollback;
